    for day, start, end in entries:
        if not (0 <= day <= 6):
            raise ValueError(f"Day must be 0..6, got {day}")
        if not (0 <= start < 1440):
            raise ValueError(f"Start must be 0..1439, got {start}")
        if end <= start:
            raise ValueError(f"End must be > start")
        length = end - start
        abs_start = (day * 1440 + start + offset) % WEEK
        abs_end = abs_start + length
        pos = abs_start
        while pos < abs_end:
            day_idx = (pos // 1440) % 7
            day_begin = (pos // 1440) * 1440
            day_end_min = day_begin + 1440
            seg_end = min(abs_end, day_end_min)
            if pos < seg_end:
                result.append((day_idx, pos - day_begin, seg_end - day_begin))
            pos = seg_end
            if pos >= WEEK and pos < abs_end:
                pos = pos % WEEK
    return sorted(result)
